import { openDb, request } from './db';

/**
 * Words you chose to keep: carved stones, and (soon) journal entries.
 * Stored encrypted on the device with AES-GCM; the key is generated by the
 * browser as non-extractable, so it can be used here but never read out.
 * Only the id, kind and date are stored in the clear, for lookups.
 */

/** Where a stone sits on its cairn. Fixed once it has settled. */
export interface StonePlacement {
  cairn: number;
  level: number;
  x: number;
  y: number;
  z: number;
  rotY: number;
  tiltX: number;
  tiltZ: number;
}

export interface StoneEntry {
  id: string;
  kind: 'stone';
  /** Local calendar date it was carved, "YYYY-MM-DD". */
  date: string;
  createdAt: string;
  text: string;
  /** Regenerates the same stone shape and color. */
  seed: number;
  place: StonePlacement;
}

export interface JournalEntry {
  id: string;
  kind: 'journal';
  date: string;
  createdAt: string;
  updatedAt: string;
  text: string;
}

export type KeptEntry = StoneEntry | JournalEntry;
export type KeptKind = KeptEntry['kind'];

export interface KeptStore {
  readonly persistent: boolean;
  put(entry: KeptEntry): Promise<void>;
  get(id: string): Promise<KeptEntry | null>;
  all<K extends KeptKind>(kind: K): Promise<Extract<KeptEntry, { kind: K }>[]>;
  onDate(date: string): Promise<KeptEntry[]>;
  /** Journal entries can be deleted. Stones can't be removed. */
  remove(id: string): Promise<void>;
}

const DATE_RE = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const MAX_TEXT = 20000;

const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

/** Validates an entry after decrypting, before it's used anywhere. */
export function isKeptEntry(v: unknown): v is KeptEntry {
  if (typeof v !== 'object' || v === null) return false;
  const e = v as Record<string, unknown>;
  if (typeof e.id !== 'string' || e.id.length === 0 || e.id.length > 64) return false;
  if (typeof e.date !== 'string' || !DATE_RE.test(e.date)) return false;
  if (typeof e.createdAt !== 'string' || typeof e.text !== 'string' || e.text.length > MAX_TEXT) return false;
  if (e.kind === 'stone') {
    const p = e.place as Record<string, unknown> | undefined;
    return isNum(e.seed) && !!p && ['cairn', 'level', 'x', 'y', 'z', 'rotY', 'tiltX', 'tiltZ'].every((k) => isNum(p[k]));
  }
  if (e.kind === 'journal') return typeof e.updatedAt === 'string';
  return false;
}

export function newId(): string {
  return crypto.randomUUID();
}

export class MemoryKeptStore implements KeptStore {
  readonly persistent: boolean = false;
  private readonly entries = new Map<string, KeptEntry>();

  async put(entry: KeptEntry): Promise<void> {
    if (!isKeptEntry(entry)) throw new Error('Not a valid kept entry');
    this.entries.set(entry.id, structuredClone(entry));
  }
  async get(id: string): Promise<KeptEntry | null> {
    return this.entries.get(id) ?? null;
  }
  async all<K extends KeptKind>(kind: K): Promise<Extract<KeptEntry, { kind: K }>[]> {
    return [...this.entries.values()].filter((e) => e.kind === kind) as Extract<KeptEntry, { kind: K }>[];
  }
  async onDate(date: string): Promise<KeptEntry[]> {
    return [...this.entries.values()].filter((e) => e.date === date);
  }
  async remove(id: string): Promise<void> {
    const e = this.entries.get(id);
    if (e?.kind === 'stone') throw new Error('Stones can’t be removed');
    this.entries.delete(id);
  }
}

interface StoredRecord {
  id: string;
  kind: KeptKind;
  date: string;
  iv: Uint8Array<ArrayBuffer>;
  data: ArrayBuffer;
}

export class IdbKeptStore implements KeptStore {
  readonly persistent: boolean = true;

  private constructor(
    private readonly db: IDBDatabase,
    private readonly key: CryptoKey,
  ) {}

  static async open(factory: IDBFactory = indexedDB): Promise<IdbKeptStore> {
    const db = await openDb(factory);
    let key: CryptoKey | undefined = await request(db.transaction('keys', 'readonly').objectStore('keys').get('main'));
    if (!key) {
      key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
      await request(db.transaction('keys', 'readwrite').objectStore('keys').put(key, 'main'));
    }
    return new IdbKeptStore(db, key);
  }

  async put(entry: KeptEntry): Promise<void> {
    if (!isKeptEntry(entry)) throw new Error('Not a valid kept entry');
    const iv = crypto.getRandomValues(new Uint8Array(new ArrayBuffer(12)));
    const plain = new TextEncoder().encode(JSON.stringify(entry));
    const data = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, this.key, plain);
    const record: StoredRecord = { id: entry.id, kind: entry.kind, date: entry.date, iv, data };
    await request(this.db.transaction('kept', 'readwrite').objectStore('kept').put(record));
  }

  async get(id: string): Promise<KeptEntry | null> {
    const r: StoredRecord | undefined = await request(this.db.transaction('kept', 'readonly').objectStore('kept').get(id));
    return r ? this.open(r) : null;
  }

  async all<K extends KeptKind>(kind: K): Promise<Extract<KeptEntry, { kind: K }>[]> {
    const rows: StoredRecord[] = await request(this.db.transaction('kept', 'readonly').objectStore('kept').index('kind').getAll(kind));
    const out = await Promise.all(rows.map((r) => this.open(r)));
    return out.filter((e): e is Extract<KeptEntry, { kind: K }> => e !== null && e.kind === kind);
  }

  async onDate(date: string): Promise<KeptEntry[]> {
    const rows: StoredRecord[] = await request(this.db.transaction('kept', 'readonly').objectStore('kept').index('date').getAll(date));
    return (await Promise.all(rows.map((r) => this.open(r)))).filter((e): e is KeptEntry => e !== null);
  }

  async remove(id: string): Promise<void> {
    const store = this.db.transaction('kept', 'readwrite').objectStore('kept');
    const r: StoredRecord | undefined = await request(store.get(id));
    if (r?.kind === 'stone') throw new Error('Stones can’t be removed');
    await request(this.db.transaction('kept', 'readwrite').objectStore('kept').delete(id));
  }

  private async open(r: StoredRecord): Promise<KeptEntry | null> {
    try {
      const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: r.iv }, this.key, r.data);
      const entry: unknown = JSON.parse(new TextDecoder().decode(plain));
      return isKeptEntry(entry) && entry.id === r.id ? entry : null;
    } catch {
      return null;
    }
  }
}

/** Opens encrypted on-device storage, falling back to memory where the browser blocks it. */
export async function openKeptStore(): Promise<KeptStore> {
  try {
    if (typeof indexedDB === 'undefined' || !crypto?.subtle) throw new Error('Unavailable');
    return await IdbKeptStore.open();
  } catch {
    return new MemoryKeptStore();
  }
}
